insert into public.legal_documents (key, title, content, version, updated_at) select key, title, content, version, updated_at from json_populate_recordset(null::public.legal_documents, E'[{"key":"privacy","title":"Politique de Confidentialité","content":"# Politique de Confidentialité\\n\\n_Document provisoire — la version finale rédigée par notre conseil juridique le remplacera prochainement._\\n\\n## 1. Données collectées\\nNous collectons les données que vous fournissez (profil, photos, préférences), votre localisation approximative (avec votre accord) et, pour la vérification d''identité, vos documents officiels.\\n\\n## 2. Finalités\\nCes données servent exclusivement à : proposer des profils compatibles à proximité, sécuriser la plateforme (vérification, modération) et améliorer le service.\\n\\n## 3. Localisation\\nVotre position précise n''est jamais montrée aux autres membres — seule une distance approximative est affichée. Vous pouvez désactiver la localisation à tout moment.\\n\\n## 4. Documents d''identité\\nLes documents KYC sont stockés chiffrés dans un espace privé, accessibles uniquement à l''équipe de vérification, et supprimés après examen.\\n\\n## 5. Partage\\nVos données ne sont jamais vendues. Elles ne sont partagées qu''avec nos sous-traitants techniques (hébergement) dans le respect du RGPD.\\n\\n## 6. Vos droits\\nVous disposez d''un droit d''accès, de rectification, de suppression et de portabilité. Exercez-les depuis les paramètres ou en écrivant à privacy@afriloveworld.com.\\n\\n## 7. Conservation\\nLes données d''un compte supprimé sont conservées de manière minimale le temps nécessaire à la prévention des fraudes et récidives de bannissement, puis anonymisées.","version":1,"updated_at":"2026-07-02T12:55:33.320715+00:00"}, {"key":"terms","title":"Conditions Générales d''Utilisation","content":"# Conditions Générales d''Utilisation\\n\\n_Document provisoire — la version finale rédigée par notre conseil juridique le remplacera prochainement._\\n\\n## 1. Objet\\nLes présentes conditions régissent l''utilisation de l''application AfriLove World, service de mise en relation destiné aux personnes majeures (18 ans et plus).\\n\\n## 2. Inscription et compte\\nVous certifiez avoir 18 ans révolus et fournir des informations exactes. Chaque personne ne peut détenir qu''un seul compte. Le compte est strictement personnel.\\n\\n## 3. Comportement\\nSont interdits : le harcèlement, les propos haineux, l''usurpation d''identité, les sollicitations commerciales et tout contenu illicite. Tout manquement peut entraîner la suspension ou le bannissement définitif du compte.\\n\\n## 4. Vérification d''identité\\nLa vérification (badge) repose sur l''examen de documents d''identité, traités de manière confidentielle et supprimés après examen.\\n\\n## 5. Abonnements\\nCertaines fonctionnalités sont payantes. Les conditions de facturation et de résiliation sont précisées au moment de l''achat.\\n\\n## 6. Responsabilité\\nAfriLove World met en relation ses membres mais ne garantit pas l''issue des rencontres. Faites preuve de prudence lors de vos échanges et rencontres.\\n\\n## 7. Résiliation\\nVous pouvez supprimer votre compte à tout moment depuis les paramètres de l''application.\\n\\n## 8. Contact\\nsupport@afriloveworld.com","version":1,"updated_at":"2026-07-02T20:31:28.979797+00:00"}]') on conflict do nothing;
